//! Independent Feynman-parameter controls for a removable HV chart limit.
//! The TSV is generated by generate_c0_projective_fixtures.py at 60/90 digits.
#![cfg(feature = "generated-evaluators")]
#[path = "support/evaluate_rows.rs"]
mod evaluate_rows;
use evaluate_rows::EvaluateRows;

use oneloop::{C0, NativeEvaluator, NativeFloat, OneLoopExpressions, ScalarIntegral};
use symbolica::{
    atom::Atom,
    domains::{
        float::{Complex, DoubleFloat, Float, RealLike},
        rational::Rational,
    },
    evaluate::{EvaluationDomain, ExpressionEvaluator},
};

fn decimal<T: NativeFloat + RealLike>(prototype: &T, value: &str) -> T {
    prototype.from_rational(&Float::parse(value, Some(384)).unwrap().to_rational())
}

fn rows<T: NativeFloat + RealLike>(prototype: &T) -> Vec<(String, Vec<Complex<T>>, T)> {
    let mut result = Vec::new();
    for line in include_str!("data/c0_projective.tsv")
        .lines()
        .filter(|s| !s.starts_with('#'))
    {
        let fields = line.split_whitespace().collect::<Vec<_>>();
        assert_eq!(fields.len(), 9);
        let values = fields[1..8]
            .iter()
            .map(|s| {
                let (num, den) = s.split_once('/').unwrap_or((s, "1"));
                let rational =
                    Rational::from((num.parse::<i64>().unwrap(), den.parse::<i64>().unwrap()));
                Complex::new(prototype.from_rational(&rational), prototype.zero())
            })
            .collect::<Vec<_>>();
        for rotation in 0..3 {
            let mut row = (0..3)
                .map(|j| values[(j + rotation) % 3].clone())
                .collect::<Vec<_>>();
            row.extend((0..3).map(|j| values[3 + (j + rotation) % 3].clone()));
            row.push(values[6].clone());
            result.push((
                format!("{} rotation{rotation}", fields[0]),
                row,
                decimal(prototype, fields[8]),
            ));
        }
    }
    assert_eq!(result.len(), 39);
    result
}

fn compare<T: NativeFloat + RealLike>(
    exact: &ExpressionEvaluator<Complex<Rational>>,
    prototype: T,
    tolerance: &str,
) where
    Complex<T>: EvaluationDomain,
{
    let bits = prototype.get_precision();
    let mut exact = exact.clone().map_coeff_with_prec(
        &|v| {
            Complex::new(
                prototype.from_rational(&v.re),
                prototype.from_rational(&v.im),
            )
        },
        bits,
    );
    let mut row_oracle = exact.clone();
    let mut native = NativeEvaluator::<T>::with_binary_precision(ScalarIntegral::C0, bits).unwrap();
    let zero = Complex::new(prototype.zero(), prototype.zero());
    let tolerance = decimal(&prototype, tolerance);
    let rows = rows(&prototype);
    let check = |label: &str, result: &[Complex<T>], expected: &T| {
        assert!(
            result.iter().all(|v| v.re.is_finite() && v.im.is_finite()),
            "{label}: {result:?}"
        );
        let error = (result[0].re.clone() - expected).norm() + result[0].im.norm();
        assert!(
            error < tolerance,
            "{label}: error={error:?}, result={result:?}, expected={expected:?}"
        );
        assert!(
            result[1..].iter().all(|v| v.re.is_zero() && v.im.is_zero()),
            "{label}: poles={result:?}"
        );
    };
    for (name, row, expected) in &rows {
        let mut result = vec![zero.clone(); 3];
        exact.evaluate(row, &mut result);
        check(&format!("interpreter {name}"), &result, expected);
        native.evaluate(row, &mut result).unwrap();
        check(&format!("native {name}"), &result, expected);
    }
    row_oracle.evaluate_rows(&[], &mut [], 0).unwrap();
    native.evaluate_batch(&[], &mut [], 0).unwrap();
    for order in [
        (0..rows.len()).collect::<Vec<_>>(),
        (0..rows.len()).rev().collect(),
    ] {
        for width in [1, 4, 16] {
            for indices in order.chunks(width) {
                let input = indices
                    .iter()
                    .flat_map(|&j| rows[j].1.iter().cloned())
                    .collect::<Vec<_>>();
                let mut output = vec![zero.clone(); 3 * indices.len()];
                row_oracle
                    .evaluate_rows(&input, &mut output, indices.len())
                    .unwrap();
                for (&j, value) in indices.iter().zip(output.chunks_exact(3)) {
                    check(
                        &format!("interpreter rows {}", rows[j].0),
                        value,
                        &rows[j].2,
                    );
                }
                native
                    .evaluate_batch(&input, &mut output, indices.len())
                    .unwrap();
                for (&j, value) in indices.iter().zip(output.chunks_exact(3)) {
                    check(&format!("native batch {}", rows[j].0), value, &rows[j].2);
                }
            }
        }
    }
}

#[test]
fn projective_zero_and_nearby_c0_match_independent_quadrature() {
    std::thread::Builder::new()
        .stack_size(128 * 1024 * 1024)
        .spawn(|| {
            let context = OneLoopExpressions::new();
            let parameters = (0..7)
                .map(|j| symbolica::symbol!(format!("projective_input_{j}")).to_atom())
                .collect::<Vec<_>>();
            let calls = [0, -1, -2].map(|tag| {
                let mut args = vec![Atom::num(tag)];
                args.extend(parameters.iter().cloned());
                C0().call(&args)
            });
            let exact = context.evaluator(&calls, &parameters).unwrap();
            compare(&exact, 0_f64, "1e-12");
            compare(&exact, DoubleFloat::from(0.), "1e-27");
            compare(&exact, Float::new(256), "1e-65");
            let rows = rows(&0_f64);
            let mut jit = context.jit_evaluator(&calls, &parameters).unwrap();
            for indices in (0..rows.len()).collect::<Vec<_>>().chunks(4) {
                let input = indices
                    .iter()
                    .flat_map(|&j| rows[j].1.iter().copied())
                    .collect::<Vec<_>>();
                let mut output = vec![Complex::new(0., 0.); 3 * indices.len()];
                jit.evaluate_batch(&input, &mut output, indices.len())
                    .unwrap();
                for (&j, value) in indices.iter().zip(output.chunks_exact(3)) {
                    assert!(
                        value.iter().all(|v| v.re.is_finite() && v.im.is_finite()),
                        "JIT {}: {value:?}",
                        rows[j].0
                    );
                    assert!(
                        (value[0].re - rows[j].2).hypot(value[0].im) < 1e-12,
                        "JIT {}: {value:?}",
                        rows[j].0
                    );
                    assert!(value[1..].iter().all(|v| v.re == 0. && v.im == 0.));
                }
            }
        })
        .unwrap()
        .join()
        .unwrap();
}
